public class ListMutatorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        java.util.List<Integer> nums = new java.util.ArrayList<>(java.util.List.of(1, 2, 3));
        ListMutator.doubleAll(nums);
        check("doubleAll [1, 2, 3]", "[2, 4, 6]", nums.toString());
        ListMutator.doubleAll(nums);
        check("doubleAll applied twice", "[4, 8, 12]", nums.toString());
        java.util.List<Integer> signs = new java.util.ArrayList<>(java.util.List.of(-3, 0, 5));
        ListMutator.doubleAll(signs);
        check("doubleAll with negatives and zero", "[-6, 0, 10]", signs.toString());
        java.util.List<Integer> noNums = new java.util.ArrayList<>();
        ListMutator.doubleAll(noNums);
        check("doubleAll on empty list", "[]", noNums.toString());
        java.util.List<String> words = new java.util.ArrayList<>(java.util.List.of("  hi ", "yo  ", "ok"));
        ListMutator.trimAll(words);
        check("trimAll strips both ends", "[hi, yo, ok]", words.toString());
        java.util.List<String> spaced = new java.util.ArrayList<>(java.util.List.of("   ", " a b "));
        ListMutator.trimAll(spaced);
        check("trimAll keeps inner spaces", "[, a b]", spaced.toString());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

