public class ListMutator {

    public static void doubleAll(java.util.List<Integer> nums) {
        nums.replaceAll(n -> n * 2);
    }

    public static void trimAll(java.util.List<String> words) {
        words.replaceAll(w -> w.trim());
    }
}
